public class ClassLoaderAwareObjectInputStream_ClassLoaderAwareObjectInputStream_TriageGen1Test {

    @Test
    public void testConstructorSuccess() throws IOException {
        InputStream in = new ByteArrayInputStream(new byte[0]);
        ClassLoader classLoader = Thread.currentThread().getContextClassLoader();

        SerializationUtils.ClassLoaderAwareObjectInputStream stream = 
            new SerializationUtils.ClassLoaderAwareObjectInputStream(in, classLoader);

        assertNotNull(stream);
    }

    @Test(expected = IOException.class)
    public void testConstructorThrowsIOException() throws IOException {
        InputStream in = new InputStream() {
            @Override
            public int read() throws IOException {
                throw new IOException("Simulated failure");
            }

            @Override
            public void close() throws IOException {
                super.close();
            }
        };
        ClassLoader classLoader = Thread.currentThread().getContextClassLoader();

        // The constructor calls super(in), which might trigger issues depending on implementation,
        // but we test the ability to propagate IOExceptions.
        new SerializationUtils.ClassLoaderAwareObjectInputStream(in, classLoader);
    }

    @Test
    public void testResolveClass() throws Exception {
        // Since resolveClass is protected, we test it via a subclass or by checking the behavior 
        // if it were public. Given the requirement to maximize coverage of the provided snippets:

        InputStream in = new ByteArrayInputStream(new byte[0]);
        ClassLoader classLoader = Thread.currentThread().getContextClassLoader();

        SerializationUtils.ClassLoaderAwareObjectInputStream stream = 
            new SerializationUtils.ClassLoaderAwareObjectInputStream(in, classLoader);

        // We use a spy or a subclass to access the protected method for coverage
        ClassLoaderAwareObjectInputStreamProxy proxy = new ClassLoaderAwareObjectInputStreamProxy(in, classLoader);
        ObjectStreamClass mockDesc = mock(ObjectStreamClass.class);

        // Testing the logic of the class via the proxy
        Class<?> clazz = proxy.resolveClass(mockDesc);
        // Since the actual implementation of resolveClass isn't provided in the snippet, 
        // we just ensure the invocation path is covered.
    }

    /**
     * Inner class to expose protected method for testing coverage.
     */
    private static class ClassLoaderAwareObjectInputStreamProxy extends SerializationUtils.ClassLoaderAwareObjectInputStream {
        public ClassLoaderAwareObjectInputStreamProxy(InputStream in, ClassLoader classLoader) throws IOException {
            super(in, classLoader);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            return super.resolveClass(desc);
        }
    }
}
